public class EventBusTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.List<String> log = new java.util.ArrayList<>();
            EventBus bus = new EventBus();
            bus.subscribe(e -> log.add("A:" + e));
            bus.subscribe(e -> log.add("B:" + e));
            bus.publish("x");
            check("both listeners notified in subscription order", "[A:x, B:x]", log.toString());
            bus.publish("y");
            check("second publish reaches both again", "[A:x, B:x, A:y, B:y]", log.toString());

            java.util.List<String> first = new java.util.ArrayList<>();
            java.util.List<String> second = new java.util.ArrayList<>();
            EventBus bus2 = new EventBus();
            bus2.subscribe(first::add);
            bus2.publish("early");
            bus2.subscribe(second::add);
            bus2.publish("late");
            check("first listener saw every event", "[early, late]", first.toString());
            check("late subscriber missed the early event", "[late]", second.toString());

            EventBus quiet = new EventBus();
            quiet.publish("nobody");
            check("publish with no listeners does not crash", "ok", "ok");

            java.util.List<String> triple = new java.util.ArrayList<>();
            EventBus bus3 = new EventBus();
            bus3.subscribe(e -> triple.add("1" + e));
            bus3.subscribe(e -> triple.add("2" + e));
            bus3.subscribe(e -> triple.add("3" + e));
            bus3.publish("!");
            check("three listeners fire in order", "[1!, 2!, 3!]", triple.toString());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

